def findN(sum):
    i = 0
    num = 0
    while num <= sum:
        num += i
        i += 1
    num -= i - 1
    i -= 2
    if num == sum:
        print(i)
    else:
        diff = sum - num
        n0 = i + 1
        d0 = n0 - diff
        if d0 % 2 == 0:
            print(n0)
        else:
            n1 = n0 + 1
            d1 = d0 + n1
            if d1 % 2 == 0:
                print(n1)
            else:
                print(n1 + 1)


x = abs(int(input()))
findN(x)

